#!/usr/bin/env dart

// Generates site/install.sh and site/install.ps1 from site/install-config.yaml.
//
// Usage:
//   dart run scripts/gen_installers.dart
//
// After editing site/install-config.yaml, rerun this script and commit the
// generated installer files. Do not edit install.sh / install.ps1 by hand.

import 'dart:io';

import 'package:yaml/yaml.dart';

const _configPath = 'site/install-config.yaml';
const _shTemplatePath = 'site/install.sh.template';
const _psTemplatePath = 'site/install.ps1.template';
const _batTemplatePath = 'site/install.bat.template';
const _shOut = 'site/install.sh';
const _psOut = 'site/install.ps1';
const _batOut = 'site/install.bat';
const _shSetupTemplatePath = 'site/setup.sh.template';
const _psSetupTemplatePath = 'site/setup.ps1.template';
const _shSetupOut = 'site/setup.sh';
const _psSetupOut = 'site/setup.ps1';

final _generatedHeader =
    '''
# ═══════════════════════════════════════════════════════════════════════════
#  DO NOT EDIT THIS FILE BY HAND. It is generated from site/install-config.yaml
#  by `dart run scripts/gen_installers.dart`.
# ═══════════════════════════════════════════════════════════════════════════
'''
        .trim();

void main() {
  final config = loadYaml(File(_configPath).readAsStringSync()) as YamlMap;
  final providers = config['providers'] as YamlList;
  final modes = config['modes'] as YamlList;
  final approvalModes = config['approval_modes'] as YamlList;
  final installConfig = config['install'] as YamlMap;

  final shBanner = _shBanner(installConfig);
  final psBanner = _psBanner(installConfig);
  final shRecipe = _shSetupRecipe(installConfig);
  final psRecipe = _psSetupRecipe(installConfig);

  // SEC-07 (#795): the default install tracks the `vpinned` release marker
  // (advanced by the tag-scoped install-pin-bump job only after signed
  // provenance) — there is deliberately NO version knob here: a pin baked
  // into a committed file rots (#1015) or demands release-pipeline commits.
  // The trust anchor below stays single-sourced.

  // gh-814 r2: the trust anchor is single-sourced here. Hard-error when the
  // config carries no parseable-looking PUBLIC KEY block — a silently
  // missing anchor would produce an installer that can never verify.
  final signingPem = (installConfig['signing_public_key'] as String? ?? '')
      .trim();
  if (!signingPem.startsWith('-----BEGIN PUBLIC KEY-----') ||
      !signingPem.endsWith('-----END PUBLIC KEY-----')) {
    throw StateError(
      'install.signing_public_key in $_configPath must be a PUBLIC KEY PEM '
      'block (the release-signing trust anchor embedded via {{SIGNING_PEM}})',
    );
  }

  final sh = File(_shTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', shBanner)
      .replaceFirst('{{SIGNING_PEM}}', signingPem)
      .replaceFirst('{{SETUP_RECIPE}}', shRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final ps = File(_psTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', psBanner)
      .replaceFirst('{{SETUP_RECIPE}}', psRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  final bat = File(_batTemplatePath).readAsStringSync().replaceFirst(
    ':: {{GENERATED_HEADER}}',
    _generatedHeader.replaceAll('# ', ':: '),
  );

  File(_shOut).writeAsStringSync(sh);
  // Windows PowerShell 5.1 parses scripts WITHOUT a BOM in the system ANSI
  // code page, which mojibakes the UTF-8 banner/glyphs at parse time (the
  // OutputEncoding line cannot fix already-corrupted literals). Writing the
  // BOM makes PS 5.1 read the file as UTF-8.
  File(_psOut).writeAsStringSync('\uFEFF$ps');
  File(_batOut).writeAsStringSync(bat);

  final shSetup = File(_shSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final psSetup = File(_psSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  File(_shSetupOut).writeAsStringSync(shSetup);
  // Same UTF-8 BOM rationale as install.ps1 (see above).
  File(_psSetupOut).writeAsStringSync('\uFEFF$psSetup');

  print(
    'Generated $_shOut, $_psOut, $_shSetupOut and $_psSetupOut from $_configPath',
  );
}

// ── Shell fragments ─────────────────────────────────────────────────────────

String _shProviderMenu(YamlList providers) {
  final b = StringBuffer();
  b.writeln(r'# Provider menu');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    final note = p['note'] ?? '';
    final rec = p['recommended'] == true ? '   (recommended)' : '';
    b.writeln('say "  ${i + 1}) ${p['name']}  — $note$rec"');
  }
  b.writeln(r'say ""');
  b.writeln(r'provider_choice=""');
  b.writeln(r'while true; do');
  b.write(r'  ask provider_choice "Pick a provider [1-');
  b.write(providers.length);
  b.writeln(r']" "1"');
  b.writeln(r'  case "$provider_choice" in');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    b.writeln(
      '    ${i + 1}|${p['id']}) provider="${p['id']}"; provider_kind="${p['kind']}"; break ;;',
    );
  }
  b.write(r'    *) warn "enter 1-');
  b.write(providers.length);
  b.writeln(r'" ;;');
  b.writeln(r'  esac');
  b.writeln(r'done');
  return b.toString();
}

String _shProviderCases(YamlList providers) {
  final b = StringBuffer();
  b.writeln(r'# Model selection');
  b.writeln(r'model=""');
  b.writeln(r'base_url=""');
  b.writeln(r'case "$provider" in');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    b.writeln('  ${p['id']})');
    if (p['custom'] == true) {
      b.writeln(r'    say ""');
      b.writeln(
        r'    ask base_url "Custom base URL (e.g. http://localhost:11434/v1)"',
      );
      b.writeln(r'    ask model "Model id on that endpoint"');
      b.writeln('    key_var="${p['key_var']}"');
    } else {
      b.writeln(r'    say ""');
      b.writeln('    say "  ${p['name']} models:"');
      final models = p['models'] as YamlList;
      for (var j = 0; j < models.length; j++) {
        final m = models[j];
        final label = m['label'] ?? m['id'];
        final rec = m['recommended'] == true ? '   (recommended)' : '';
        b.writeln('    say "    ${j + 1}) $label$rec"');
      }
      b.writeln(
        '    say "    ${models.length + 1}) other — enter model id manually"',
      );
      b.writeln(r'    while true; do');
      b.writeln(r'      ask model "Pick a model" "1"');
      b.writeln(r'      case "$model" in');
      for (var j = 0; j < models.length; j++) {
        final m = models[j];
        b.writeln('        ${j + 1}) model="${m['id']}"; break ;;');
      }
      b.writeln(
        '        ${models.length + 1}) ask model "Enter the ${p['name']} model id"; break ;;',
      );
      b.write(r'        *) warn "enter 1-');
      b.write(models.length + 1);
      b.writeln(r'" ;;');
      b.writeln(r'      esac');
      b.writeln(r'    done');
      b.writeln('    base_url="${p['base_url']}"');
      b.writeln('    key_var="${p['key_var']}"');
    }
    b.writeln(r'    ;;');
  }
  b.writeln(r'esac');
  return b.toString();
}

String _shModeMenu(YamlList modes) {
  final b = StringBuffer();
  b.writeln(r'# Mode selection');
  b.writeln(r'say ""');
  b.writeln(r'say "  Agent modes:"');
  for (var i = 0; i < modes.length; i++) {
    final m = modes[i];
    final note = m['note'] ?? '';
    final rec = m['default'] == true ? ' (default)' : '';
    b.writeln('say "    ${i + 1}) ${m['id']}$rec  — $note"');
  }
  return b.toString();
}

String _shModeCases(YamlList modes) {
  final b = StringBuffer();
  b.writeln(r'mode=""');
  b.writeln(r'while true; do');
  b.writeln(r'  ask mode "Pick a mode" "1"');
  b.writeln(r'  case "$mode" in');
  for (var i = 0; i < modes.length; i++) {
    final m = modes[i];
    b.writeln('    ${i + 1}|${m['id']}) mode="${m['id']}"; break ;;');
  }
  b.write(r'    *) warn "enter 1-');
  b.write(modes.length);
  b.writeln(r'" ;;');
  b.writeln(r'  esac');
  b.writeln(r'done');
  return b.toString();
}

String _shApprovalMenu(YamlList approvalModes) {
  final b = StringBuffer();
  b.writeln(r'# Approval mode');
  b.writeln(r'say ""');
  b.writeln(r'say "  Tool approval:"');
  for (var i = 0; i < approvalModes.length; i++) {
    final a = approvalModes[i];
    final note = a['note'] ?? '';
    final rec = a['default'] == true ? ' (default)' : '';
    b.writeln('say "    ${i + 1}) ${a['id']}$rec  — $note"');
  }
  return b.toString();
}

String _shApprovalCases(YamlList approvalModes) {
  final b = StringBuffer();
  b.writeln(r'approval=""');
  b.writeln(r'while true; do');
  b.writeln(r'  ask approval "Pick an approval mode" "1"');
  b.writeln(r'  case "$approval" in');
  for (var i = 0; i < approvalModes.length; i++) {
    final a = approvalModes[i];
    b.writeln('    ${i + 1}|${a['id']}) approval="${a['id']}"; break ;;');
  }
  b.write(r'    *) warn "enter 1-');
  b.write(approvalModes.length);
  b.writeln(r'" ;;');
  b.writeln(r'  esac');
  b.writeln(r'done');
  return b.toString();
}

// ── PowerShell fragments ────────────────────────────────────────────────────
// In this section every `$` that should appear in the generated .ps1 file is
// written as `\$` so Dart's string interpolation ignores it. Dart `${...}` is
// still used for values coming from install-config.yaml.

String _psProviderMenu(YamlList providers) {
  final b = StringBuffer();
  b.writeln('# Provider menu');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    final note = p['note'] ?? '';
    final rec = p['recommended'] == true ? '   (recommended)' : '';
    b.writeln('Write-Host "  ${i + 1}) ${p['name']}  — $note$rec"');
  }
  b.writeln(r'Write-Host ""');
  final valid = <String>[];
  for (var i = 0; i < providers.length; i++) {
    valid.add('"${i + 1}"');
  }
  for (var i = 0; i < providers.length; i++) {
    valid.add('"${providers[i]['id']}"');
  }
  b.writeln(
    '\$providerChoice = Read-Choice "Pick a provider [1-${providers.length}]" @(${valid.join(', ')})',
  );
  return b.toString();
}

String _psProviderSwitch(YamlList providers) {
  final b = StringBuffer();
  b.writeln('switch -Regex (\$providerChoice) {');
  for (var i = 0; i < providers.length; i++) {
    final p = providers[i];
    b.writeln('    "^(${i + 1}|${p['id']})\$" {');
    b.writeln('        \$provider = "${p['id']}"');
    b.writeln('        \$providerKind = "${p['kind']}"');
    if (p['custom'] == true) {
      b.writeln(
        '        \$baseUrl = Read-Host "Custom base URL (e.g. http://localhost:11434/v1)"',
      );
      b.writeln('        \$model = Read-Host "Model id on that endpoint"');
      b.writeln('        \$keyVar = "${p['key_var']}"');
    } else {
      b.writeln(r'        Write-Host ""');
      b.writeln('        Write-Host "  ${p['name']} models:"');
      final models = p['models'] as YamlList;
      for (var j = 0; j < models.length; j++) {
        final m = models[j];
        final label = m['label'] ?? m['id'];
        final rec = m['recommended'] == true ? '   (recommended)' : '';
        b.writeln('        Write-Host "    ${j + 1}) $label$rec"');
      }
      b.writeln(
        '        Write-Host "    ${models.length + 1}) other — enter model id manually"',
      );
      final valid = List.generate(
        models.length + 1,
        (j) => '"${j + 1}"',
      ).join(', ');
      b.writeln(
        '        \$m = Read-Choice "Pick a model [1-${models.length + 1}]" @($valid)',
      );
      b.writeln('        switch (\$m) {');
      for (var j = 0; j < models.length; j++) {
        b.writeln('            "${j + 1}" { \$model = "${models[j]['id']}" }');
      }
      b.writeln(
        '            "${models.length + 1}" { \$model = Read-Host "Enter the ${p['name']} model id" }',
      );
      b.writeln(r'        }');
      b.writeln('        \$baseUrl = "${p['base_url']}"');
      b.writeln('        \$keyVar = "${p['key_var']}"');
    }
    b.writeln(r'    }');
  }
  b.writeln(r'}');
  return b.toString();
}

String _psModeMenu(YamlList modes) {
  final b = StringBuffer();
  b.writeln('# Mode selection');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Agent modes:"');
  for (var i = 0; i < modes.length; i++) {
    final m = modes[i];
    final note = m['note'] ?? '';
    final rec = m['default'] == true ? ' (default)' : '';
    b.writeln('Write-Host "    ${i + 1}) ${m['id']}$rec  — $note"');
  }
  return b.toString();
}

String _psModeSwitch(YamlList modes) {
  final b = StringBuffer();
  final valid = <String>[];
  for (var i = 0; i < modes.length; i++) {
    valid.add('"${i + 1}"');
    valid.add('"${modes[i]['id']}"');
  }
  b.writeln(
    '\$modeChoice = Read-Choice "Pick a mode [1-${modes.length}]" @(${valid.join(', ')})',
  );
  b.writeln('switch -Regex (\$modeChoice) {');
  for (var i = 0; i < modes.length; i++) {
    final m = modes[i];
    b.writeln('    "^(${i + 1}|${m['id']})\$" { \$mode = "${m['id']}" }');
  }
  b.writeln(r'}');
  return b.toString();
}

String _psApprovalMenu(YamlList approvalModes) {
  final b = StringBuffer();
  b.writeln('# Approval mode');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Tool approval:"');
  for (var i = 0; i < approvalModes.length; i++) {
    final a = approvalModes[i];
    final note = a['note'] ?? '';
    final rec = a['default'] == true ? ' (default)' : '';
    b.writeln('Write-Host "    ${i + 1}) ${a['id']}$rec  — $note"');
  }
  return b.toString();
}

String _psApprovalSwitch(YamlList approvalModes) {
  final b = StringBuffer();
  final valid = <String>[];
  for (var i = 0; i < approvalModes.length; i++) {
    valid.add('"${i + 1}"');
    valid.add('"${approvalModes[i]['id']}"');
  }
  b.writeln(
    '\$approvalChoice = Read-Choice "Pick an approval mode [1-${approvalModes.length}]" @(${valid.join(', ')})',
  );
  b.writeln('switch -Regex (\$approvalChoice) {');
  for (var i = 0; i < approvalModes.length; i++) {
    final a = approvalModes[i];
    b.writeln('    "^(${i + 1}|${a['id']})\$" { \$approval = "${a['id']}" }');
  }
  b.writeln(r'}');
  return b.toString();
}

// ── Shared installer banner / setup recipe ──────────────────────────────────

String _shBanner(YamlMap install) {
  final b = StringBuffer();
  b.writeln(r'say ""');
  for (final line in install['banner'] as YamlList) {
    b.writeln('say "$line"');
  }
  b.writeln(r'say ""');
  b.writeln('say "  ${install['tagline']}"');
  b.writeln(r'say ""');
  return b.toString();
}

String _psBanner(YamlMap install) {
  final b = StringBuffer();
  b.writeln(r'Write-Host ""');
  for (final line in install['banner'] as YamlList) {
    b.writeln('Write-Host "$line"');
  }
  b.writeln(r'Write-Host ""');
  b.writeln('Write-Host "  ${install['tagline']}"');
  b.writeln(r'Write-Host ""');
  return b.toString();
}

String _shSetupRecipe(YamlMap install) {
  final setupUrl = install['setup_url_sh'] as String;
  final vars = (install['key_env_vars'] as YamlList).cast<String>();
  final docsUrl = install['docs_url'] as String;
  final packageUrl = install['package_url'] as String;
  final task = install['example_task'] as String;
  final firstVar = vars.first;
  final restVars = vars.skip(1).join(' / ');

  final b = StringBuffer();
  b.writeln(r'say ""');
  b.writeln(r'ok "Installation complete."');
  b.writeln(r'say ""');
  b.writeln(r'say "  Configure a provider and API key interactively:"');
  b.writeln(r'say ""');
  b.writeln('say "    curl -fsSL $setupUrl | sh"');
  b.writeln(r'say ""');
  b.writeln(r'say "  Or set an environment variable manually:"');
  b.writeln(r'say ""');
  b.writeln('say "    export $firstVar=<your-key>   # or $restVars"');
  b.writeln(r'say ""');
  b.writeln(r'say "  Then start the agent:"');
  b.writeln(r'say ""');
  b.writeln(r'say "    fa"');
  b.writeln(r'say ""');
  b.writeln(r'say "  Or run a single headless task:"');
  b.writeln(r'say ""');
  b.writeln('say "    fa \\"$task\\""');
  b.writeln(r'say ""');
  b.writeln("say \"  (the legacy command 'fah' also works)\"");
  b.writeln(r'say ""');
  b.writeln('say "  Docs:    $docsUrl"');
  b.writeln('say "  Package: $packageUrl"');
  b.writeln(r'say ""');
  return b.toString();
}

String _psSetupRecipe(YamlMap install) {
  final setupUrl = install['setup_url_ps'] as String;
  final vars = (install['key_env_vars'] as YamlList).cast<String>();
  final docsUrl = install['docs_url'] as String;
  final packageUrl = install['package_url'] as String;
  final task = install['example_task'] as String;
  final firstVar = vars.first;
  final restVars = vars.skip(1).join(' / ');

  final b = StringBuffer();
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Ok "Installation complete."');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Configure a provider and API key interactively:"');
  b.writeln(r'Write-Host ""');
  b.writeln('Write-Host "    irm $setupUrl | iex"');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Or set an environment variable manually:"');
  b.writeln(r'Write-Host ""');
  b.writeln(
    "Write-Host \"    `\$env:$firstVar = '<your-key>'   # or $restVars\"",
  );
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Then start the agent:"');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "    fa"');
  b.writeln(r'Write-Host ""');
  b.writeln(r'Write-Host "  Or run a single headless task:"');
  b.writeln(r'Write-Host ""');
  b.writeln('Write-Host "    fa `"$task`""');
  b.writeln(r'Write-Host ""');
  b.writeln("Write-Host \"  (the legacy command 'fah' also works)\"");
  b.writeln(r'Write-Host ""');
  b.writeln('Write-Host "  Docs:    $docsUrl"');
  b.writeln('Write-Host "  Package: $packageUrl"');
  b.writeln(r'Write-Host ""');
  return b.toString();
}

