    'always-ask' || 'alwaysAsk' => ApprovalMode.alwaysAsk,
    'write' => ApprovalMode.write,
    'yolo' => ApprovalMode.yolo,
    kAutopilotLabel || 'unattended' => ApprovalMode.unattended,
    _ => null,
  };
}

