          violations,
          isEmpty,
          reason: '$artifact carries POSIX-violating constructs — the '
              '#1596 crash class (dash aborts at the first bashism). Fix '
              'the SOURCE (template) and regenerate, never hand-patch the '
              'artifact. Offending: ${violations.join(", ")}',
        );
      });
