  '${var[n]} array subscript': RegExp(r'\$\{[A-Za-z_][A-Za-z0-9_]*\['),
  '${!var} indirect expansion (bash)': RegExp(r'\$\{!'),
  '${var:1:2} substring (bash)': RegExp(r'\$\{[A-Za-z_][A-Za-z0-9_]*:\s*-?[0-9]'),
  '|& co-process pipe (bash)': RegExp(r'\|&'),
};

