}

/// Full-line comments are dead text (`install.sh` self-documents with
/// "no arrays/[[]]/pipefail" and the PEM block carries base64 `==`) —
/// the lint judges only executable bytes.
String _stripCommentLines(String source) => source
    .split('\n')
