  /// (better suited for flutter debug mode).
  ///
  /// The [raw] flag puts the terminal into raw mode on Unix. By default, Unix
  /// pseudo-terminals operate in canonical mode with ECHO enabled. This means
  /// the kernel buffers input line-by-line and physically echoes characters back.
  /// If you are transferring binary data, streaming high-throughput buffers, or
  /// do not want the kernel to mangle line endings and echo data, set [raw] to true.
  static PseudoTerminal start(
    String executable,
    List<String> arguments, {
    String? workingDirectory,
    Map<String, String>? environment,
    bool ackProcessed = false,
    bool raw = false,
    // bool includeParentEnvironment = true,
    // bool runInShell = false,
    // ProcessStartMode mode = ProcessStartMode.normal,
  }) {
    late PtyCore core;

    if (Platform.isWindows) {
      core = PtyCoreWindows.start(
        executable,
        arguments,
        workingDirectory: workingDirectory,
        environment: environment,
      );
    } else {
      core = PtyCoreUnix.start(
        executable,
        arguments,
        workingDirectory: workingDirectory,
        environment: environment,
        raw: raw,
      );
    }

    return BlockingPseudoTerminal(core, ackProcessed)..init();
  }

  /// Initializes the pseudo-terminal process.
72:  /// A future that completes with the exit code of the process when it terminates.
73:  Future<int> get exitCode;
  factory PtyCoreUnix.start(
    String executable,
    List<String> arguments, {
    String? workingDirectory,
    Map<String, String>? environment,
    bool raw = false,
  }) {
    var effectiveEnv = <String, String>{};

    effectiveEnv['TERM'] = 'xterm-256color';
    // Without this, tools like "vi" produce sequences that are not UTF-8 friendly
    effectiveEnv['LANG'] = 'en_US.UTF-8';

    var envValuesToCopy = [
      'LOGNAME',
      'USER',
      'DISPLAY',
      'LC_TYPE',
      'HOME',
      'PATH',
    ];

    for (var entry in Platform.environment.entries) {
      if (envValuesToCopy.contains(entry.key)) {
        effectiveEnv[entry.key] = entry.value;
      }
    }

    if (environment != null) {
      for (var entry in environment.entries) {
        effectiveEnv[entry.key] = entry.value;
      }
    }

    var resolvedExecutable = executable;
    if (!resolvedExecutable.contains('/')) {
      final pathEnv =
          effectiveEnv['PATH'] ?? Platform.environment['PATH'] ?? '';
      for (final dir in pathEnv.split(':')) {
        if (dir.isEmpty) continue;
        final testPath = '$dir/$executable';
        if (File(testPath).existsSync()) {
          resolvedExecutable = testPath;
          break;
