    test('the provider case list equals the catalog (+ custom last)', () {
      final cases = providerCase
          .allMatches(setup)
          .map((m) => (index: int.parse(m.group(1)!), id: m.group(2)!))
          .toList();
      expect(
        cases.map((c) => c.id).toList(),
