        final testPath = '$dir/$executable';
        if (File(testPath).existsSync()) {
          resolvedExecutable = testPath;
          break;
        }
      }
    }

    return using((Arena arena) {
      final nativeExecutable = resolvedExecutable.toNativeUtf8(
