import 'dart:io';
import '../scripts/gen_installers.dart' as gen;

void main() {
  final r = gen.renderInstallers();
  for (final e in r.entries) {
    final committed = File(e.key).readAsStringSync();
    final rendered = e.value;
    if (committed == rendered) {
      print('${e.key}: identical');
    } else {
      print('${e.key}: DIFFERS len ${committed.length} vs ${rendered.length}');
      for (var i = 0; i < committed.length && i < rendered.length; i++) {
        if (committed[i] != rendered[i]) {
          print('  first diff at $i: committed=${committed.codeUnitAt(i)} '
              'rendered=${rendered.codeUnitAt(i)}');
          print('  ctx committed: ${committed.substring(i, i + 40)}');
          print('  ctx rendered : ${rendered.substring(i, i + 40)}');
          break;
        }
      }
    }
  }
}
EOF
