      ..writeAsStringSync('#!/bin/sh\necho fa-fixture-1596\n')
      ..createSync(recursive: true);
    Process.runSync('chmod', ['+x', '${shim.path}/fa']);
    path = '${shim.path}:${Platform.environment['PATH'] ?? '/usr/bin:/bin'}';
  }

