class _PtyRun {
  _PtyRun._(this.pty, this.buffer);
  final PseudoTerminal pty;
  final StringBuffer buffer;
  var done = false;

  /// Waits until [text] (ANSI-stripped) appears in the captured output.
  Future<void> waitPrompt(String text) async {
    final deadline =
