  required _Fixture fixture,
  List<String> shellArgs = const [],
  String shellEnv = '',
}) {
  final script = '${_repoRoot()}/site/setup.sh';
  final inner = [shell, ...shellArgs].join(' ');
  return _spawn(
    shell,
    [
      ...shellArgs,
      '-c',
      'cat "\$1" | $inner; echo \$? > "\$2"',
      'wizard',
