  required _Fixture fixture,
  String shellEnv = '',
}) {
  final buffer = StringBuffer();
  final pty = PseudoTerminal.start(
    executable,
    arguments,
    workingDirectory: _repoRoot(),
    environment: {
      'HOME': fixture.home.path,
      'PATH': fixture.path,
      'SHELL': shellEnv,
